import { Component, OnDestroy, OnInit } from '@angular/core';
import { Router } from '@angular/router';
import { Subject, takeUntil } from 'rxjs';
import { User } from './core/interfaces/user';
import { AuthService } from './core/services/auth.service';

@Component({
  selector: 'app-root',
  templateUrl: './app.component.html',
  styleUrls: ['./app.component.css']
})
export class AppComponent implements OnInit, OnDestroy {
  currentUser: User | null = null;
  logoutError = '';
  private readonly destroy$ = new Subject<void>();

  constructor(
    private readonly authService: AuthService,
    private readonly router: Router
  ) {}

  ngOnInit(): void {
    this.authService.currentUser$
      .pipe(takeUntil(this.destroy$))
      .subscribe((user) => (this.currentUser = user));
  }

  logout(): void {
    this.logoutError = '';
    this.authService.logout().subscribe({
      next: () => {
        this.router.navigate(['/login']);
      },
      error: (error: Error) => {
        this.logoutError = error.message;
        this.authService.forceLogout();
        this.router.navigate(['/login']);
      }
    });
  }

  ngOnDestroy(): void {
    this.destroy$.next();
    this.destroy$.complete();
  }
}
<header class="topbar">
  <div class="container topbar-content">
    <a class="brand" routerLink="/home">
      <img class="brand-logo" src="assets/photo_5409257004758405462_y.jpg" alt="DaDa Pizza logo" />
      <span>
        <strong>DaDa Pizza</strong>
        <small>Pizza made with love</small>
      </span>
    </a>

    <nav class="nav-links">
      <a routerLink="/home" routerLinkActive="active">Home</a>
      <a routerLink="/menu" routerLinkActive="active">Menu</a>
      <a routerLink="/cart" routerLinkActive="active">Cart</a>
      @if (!currentUser) {
        <a routerLink="/login" routerLinkActive="active">Login</a>
      }
    </nav>

    <div class="user-actions">
      @if (currentUser) {
        <div class="user-pill">
          <span>Signed as DaDa lover</span>
        </div>
        <button class="btn btn-secondary" type="button" (click)="logout()">Logout</button>
      } @else {
        <a class="btn btn-primary" routerLink="/menu">Order now</a>
      }
    </div>
  </div>
</header>

@if (logoutError) {
  <div class="container topbar-error">
    <div class="message error">{{ logoutError }}</div>
  </div>
}

<main>
  <router-outlet></router-outlet>
</main>
